"""Generate current narrative tables from CURRENT_ANALYSIS.json before Quarto render."""
import json
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo


def estimate(e):
    return f"{e['hr']:.3f} ({e['lower_95']:.3f}–{e['upper_95']:.3f})"


def pvalue(p):
    return f"{p:.5f}" if p >= 0.00001 else "<0.00001"


def generate(repo):
    r = json.loads((repo / "docs/CURRENT_ANALYSIS.json").read_text())
    date = datetime.fromisoformat(r["execution"]["generated_at_utc"]).astimezone(ZoneInfo("Asia/Tokyo")).strftime("%Y-%m-%d")
    m = r["models"]
    primary = m["primary_refined"]["estimates"]["raas_pre_icu"]
    core = m["core"]["estimates"]["raas_pre_icu"]
    summary = [f"# Current Results ({date})", "", f"Analysis version: `{r['analysis_version']}`. These estimates and the figures use regenerated analysis tables and continuous elapsed follow-up.", "",
               f"The cohort contains {r['n']:,} admissions and {r['deaths']:,} in-hospital deaths. Refined primary RAAS HR: {estimate(primary)}, p={pvalue(primary['p'])}. Extended core RAAS HR: {estimate(core)}, p={pvalue(core['p'])}.", "", "| Model | RAAS HR (95% CI) | p |", "| --- | --- | ---: |"]
    names = {"primary_refined": "Primary refined", "core": "Extended core", "core_penalized": "Core + L2 (0.1)",
             "icu_pooled": "ICU adjusted (rare types pooled)", "icu_pooled_penalized": "ICU pooled + L2 (0.01)",
             "core_ph_stratified": "Core CHF/SOFA strata (exploratory)", "icu_ph_stratified": "ICU CHF/SOFA/type strata (exploratory)"}
    model_rows = []
    for key, label in names.items():
        e = m[key]["estimates"]["raas_pre_icu"]
        model_rows.append(f"| {label} | {estimate(e)} | {pvalue(e['p'])} |")
    summary += model_rows + ["", "Subclass estimates compare ACEi or ARB monotherapy with no exposure; dual exposure is excluded.", "", "| Subclass | HR (95% CI) | p |", "| --- | --- | ---: |"]
    for label, cov in [("ACEi", "acei_pre_icu"), ("ARB", "arb_pre_icu")]:
        e = m["subgroups"]["estimates"][cov]
        summary.append(f"| {label} | {estimate(e)} | {pvalue(e['p'])} |")
    summary += ["", "## Diagnostics and interpretation", "", "The core and pooled ICU models retain their original covariate structure. Additional exploratory models stratify baseline hazards by era, CHF and exact SOFA; the ICU variant also stratifies by pooled ICU type. These models do not estimate CHF or SOFA coefficients. They supplement the primary analysis and are not chosen by searching for non-significant PH tests.", "", "| Model | Number of strata | Rank PH tests with p<0.05 | Model warnings |", "| --- | ---: | --- | --- |"]
    for key, label in names.items():
        failures = [f"{c} ({pvalue(p)})" for c,p in m[key]["ph_rank_p"].items() if p < .05]
        summary.append(f"| {label} | {m[key]['strata_count']} | {', '.join(failures) or 'None detected'} | {'; '.join(m[key]['warnings']).replace(chr(10),' ') or 'None'} |")
    summary += ["", "A non-significant PH test does not establish that the PH assumption is true. The exploratory ICU-stratified RAAS point estimate is above 1 while its confidence interval includes 1, demonstrating sensitivity to adjustment structure. The ICU-stratified model retains a diabetes PH flag, so the diagnostic issues are not universally resolved. Stratified models permit different baseline hazards for the stratifying covariates; their estimates are conditional on these strata, some of which are sparse. The sensitivity specifications are exploratory responses to diagnostics in this dataset.", "", f"Rare ICU labels with fewer than {r['rare_icu_rule']['minimum_admissions']} admissions are pooled using admission counts alone, independently of outcome. The pooled labels are: {', '.join(r['rare_icu_rule']['pooled_labels']) or 'none'}.", "", "This observational admission-level analysis retains discharge censoring and does not account for within-patient correlation or implement competing risks. Year-based age remains approximate, especially for the anchor-age 91 group. Residual confounding remains possible.", "", "## Independent SAS validation status", "", "Python secondary logistic parameters have been regenerated from the current BigQuery table. Current cross-platform agreement is **pending an independent SAS rerun**. Historical SAS parameters are rejected by the provenance and exact-parameter-key guards; historical numerical agreement is not evidence for the corrected dataset.", "", "SAS 07 now exports distinct era-stratified primary 04a and extended core 04c models. SAS 01 no longer prints patient records. The versioned private input query is `sql/06_export_sas_validation.sql`; no individual SAS input was exported during this refresh.", "", "The refreshed figures contain aggregate results only. Full estimates and PH p-values are in [CURRENT_ANALYSIS.json](CURRENT_ANALYSIS.json). The earlier age/time comparison remains an archived validation snapshot in [AGE_TIME_REVALIDATION.md](AGE_TIME_REVALIDATION.md).", "", "PH methods reference: [lifelines stratification documentation](https://lifelines.readthedocs.io/en/latest/jupyter_notebooks/Proportional%20hazard%20assumption.html#Stratification)."]
    (repo / "docs/RESULTS_SUMMARY.md").write_text("\n".join(summary)+"\n")

    def quantile_row(column):
        cells=[]
        for key in ["overall","no_raas","raas"]:
            q1,median,q3=r["baseline"][key]["quantiles"][column]
            cells.append(f"{median:g} ({q1:g}–{q3:g})")
        return " | ".join(cells)
    def count_row(column):
        cells=[]
        for key in ["overall","no_raas","raas"]:
            group=r["baseline"][key];v=group[column]
            cells.append(f"{v:,} ({100*v/group['n']:.1f}%)")
        return " | ".join(cells)
    primary_ph=m["primary_refined"]["ph_rank_p"]
    qmd=['---','title: "RAAS Blockers and In-Hospital Mortality in ICU Admissions With COPD"','author: "Makoto Yoshida, PhD"','format:','  html:','    toc: true','    number-sections: true','    theme: cosmo','---','',f"Updated {date} from analysis version `{r['analysis_version']}`. Generated from aggregate [current results](CURRENT_ANALYSIS.json).",'', '## Executive summary','',f"In {r['n']:,} COPD ICU admissions, pre-ICU RAAS exposure was associated with lower observed in-hospital mortality hazard in the refined age/sex-adjusted, era-stratified Cox model (HR {estimate(primary)}; p={pvalue(primary['p'])}). Extended core adjustment attenuated the association (HR {estimate(core)}; p={pvalue(core['p'])}). These estimates are observational associations and cannot establish a treatment effect.", '', '## Data source and cohort','', 'MIMIC-IV v3.1 admissions with the existing ICD-9/10 COPD definition were anchored to the first ICU stay within each hospital admission. Patients may contribute repeated admissions. Adult selection uses `anchor_age + admission_year - anchor_year >= 18`. The same admission-age estimate is preserved through baseline and outcome construction. `anchor_age=91` denotes an aggregated age group above 89 in the anchor year, so year adjustment does not recover an exact age.', '', '| Characteristic | Overall | No RAAS | RAAS |','| --- | ---: | ---: | ---: |',f"| Admissions | {r['n']:,} | {r['baseline']['no_raas']['n']:,} | {r['baseline']['raas']['n']:,} |",f"| Age, median (IQR), years | {quantile_row('age')} |",f"| Male sex | {count_row('male')} |",f"| SOFA, median (IQR) | {quantile_row('sofa_score')} |",f"| Charlson index, median (IQR) | {quantile_row('charlson_comorbidity_index')} |",f"| ICU LOS, median (IQR), days | {quantile_row('icu_los')} |",f"| Hospital LOS, median (IQR), days | {quantile_row('hosp_los')} |",f"| CHF | {count_row('chf')} |",f"| CKD | {count_row('ckd')} |",f"| Diabetes | {count_row('diabetes')} |",f"| In-hospital death | {count_row('deaths')} |",'', '## Exposure, outcome, and methods','', 'Exposure is based on inpatient ACEi/ARB prescription orders before or at ICU admission. It does not directly measure outpatient chronic use or adherence. Follow-up begins at ICU admission and ends at recorded in-hospital death or live discharge. Discharge time is used for death only when death time is missing, with an explicit fallback flag. All intervals, including ICU and hospital LOS, are calculated from DATETIME microsecond differences divided by 86,400,000,000. Death/discharge timestamps, event values, positive follow-up, and downstream lineage are validated before analysis.', '', f"There were {r['fallback_deaths']} fallback deaths. Live discharge is censored; a competing-risk framework is not implemented. Cox models use admission-level records without patient clustering or frailty. Primary 04a adjusts for age and sex and stratifies by anchor year group. Core 04c additionally adjusts for SOFA, CHF, CKD and diabetes. ICU sensitivity models add pooled ICU types; penalties remain 0.1 for core and 0.01 for ICU. Original unpooled ICU estimates are retained in the archived age/time audit.", '', '## Kaplan-Meier results','', f"The two-group log-rank statistic was {r['logrank']['statistic']:.3f}, p={pvalue(r['logrank']['p'])}. These are unadjusted survival estimates under live-discharge censoring, not competing-risk-adjusted hospital death probabilities.", '', '![Current Kaplan-Meier estimates](assets/kaplan_meier_curve.png)', '', '## Primary and extended Cox results','', '| Specification | RAAS HR (95% CI) | p |','| --- | --- | ---: |', f"| Initial 04a: era entered as covariate | {estimate(r['initial_primary'])} | {pvalue(r['initial_primary']['p'])} |"]+model_rows+['', '![Extended core Cox estimates](assets/cox_forest_plot.png)', '', '![Current sensitivity comparison](assets/cox_model_sensitivity_comparison.svg)', '', '## Subclass comparison', '', f"The monotherapy/neither analysis includes {m['subgroups']['n']:,} admissions. Its global three-group log-rank statistic is {r['subgroup_logrank']['statistic']:.3f}, p={pvalue(r['subgroup_logrank']['p'])}. Dual-exposure admissions are excluded. Each coefficient compares a subclass with neither exposure; this is not a formal ACEi-versus-ARB interaction test.", '', '![Current ACEi/ARB estimates](assets/raas_subgroup_forest_plot.svg)', '', '## PH diagnostics and interpretation', '', f"Primary refined rank PH p-values: age {pvalue(primary_ph['age'])}, sex {pvalue(primary_ph['gender_M'])}, RAAS {pvalue(primary_ph['raas_pre_icu'])}. Core and ICU models still require diagnostic interpretation. The current results summary records every covariate-level PH test and warning. Exploratory CHF/SOFA-stratified models allow different baseline hazards; they supplement the primary model rather than redefine it.", '', 'For full diagnostics, sparse-strata limitations and rare-category pooling, see [current results](RESULTS_SUMMARY.md). The approach follows [lifelines documentation on stratification](https://lifelines.readthedocs.io/en/latest/jupyter_notebooks/Proportional%20hazard%20assumption.html#Stratification). A non-significant diagnostic does not prove PH, and additional stratification changes the adjustment structure.', '', '## SAS-Python reproducibility status', '', 'Python secondary logistic coefficients have been refreshed. Independent SAS rerun and current cross-platform validation are **pending** because no local SAS runtime is available. Historical SAS outputs are not used to claim agreement for this analysis. Both outputs must have matching current cohort/model provenance and exact parameter keys before notebook 05 compares them. SAS code now distinguishes primary 04a and extended core 04c and omits all patient previews.', '', '## Limitations', '', 'These findings cannot establish causality. Confounding by indication, unmeasured severity, exposure misclassification and a single health system limit interpretation. Age is approximate, especially in the aggregated oldest group. Repeated admissions are not clustered; live discharge remains censoring; rare ICU pooling and PH-responsive strata are exploratory sensitivity choices. SAS validation is pending and must not be presented as completed.', '', '## Reproduction and sources', '', 'Run the upstream SQL, then `.venv/bin/python scripts/current_analysis.py`, `.venv/bin/python scripts/render_current_report.py`, and `.venv/bin/python scripts/build_report.py` from the repository root. Notebooks 04a–04d use the same model/figure functions. Generated notebook outputs are stripped before commit. No patient records or identifiers are included in the aggregate outputs.', '', '- [MIMIC-IV v3.1](https://physionet.org/content/mimiciv/3.1/)', '- [Methods overview](METHODS_OVERVIEW.md)', '- [Validation notes](VALIDATION_NOTES.md)', '- [Current aggregate model results](CURRENT_ANALYSIS.json)', '- [Original age/time correction audit](AGE_TIME_REVALIDATION.md)', '- [SAS workflow](https://github.com/makotoy56/mimic-iv-copd-raas-analysis/blob/main/sas/README.md)']
    (repo / "reports/copd_raas_survival_report.qmd").write_text("\n".join(qmd)+"\n")


if __name__ == "__main__":
    generate(Path(__file__).resolve().parents[1])
